  --radius: 4px;
  --transition: 200ms ease;
}

*, *::before, *::after {
  box-sizing: border-box;
  margin: 0;
  padding: 0;
}

html {
  scroll-behavior: smooth;
}

body {
  font-family: var(--font-body);
  background: var(--bg-primary);
  color: var(--text-white);
  line-height: 1.6;
  -webkit-font-smoothing: antialiased;
}

h1, h2, h3, h4, h5, h6 {
  font-family: var(--font-heading);
  font-weight: 600;
  text-transform: uppercase;
  letter-spacing: 0.05em;
  line-height: 1.2;
}

a {
  color: inherit;
  text-decoration: none;
}

img {
  max-width: 100%;
  height: auto;
}

/* Navigation */
.nav {
  position: fixed;
  top: 0;
  left: 0;
  right: 0;
  z-index: 1000;
  background: rgba(17, 17, 17, 0.95);
  backdrop-filter: blur(10px);
  border-bottom: 1px solid var(--border-color);
}

.nav-inner {
  max-width: 1400px;
  margin: 0 auto;
  padding: 1rem 2rem;
  display: flex;
  align-items: center;
  justify-content: space-between;
}

.logo {
  font-family: var(--font-heading);
  font-size: 1.5rem;
  font-weight: 700;
  color: var(--red-primary);
  text-transform: uppercase;
  letter-spacing: 0.1em;
}

.logo span {
  color: var(--text-white);
}

.nav-links {
  display: flex;
  gap: 2rem;
  list-style: none;
}

.nav-links a {
  font-family: var(--font-heading);
  font-size: 0.875rem;
  text-transform: uppercase;
  letter-spacing: 0.1em;
  color: var(--text-gray);
  transition: color var(--transition);
}

.nav-links a:hover,
.nav-links a.active {
  color: var(--red-primary);
}

.nav-cta {
  display: flex;
  gap: 1rem;
}

.btn {
  font-family: var(--font-heading);
  font-size: 0.875rem;
  font-weight: 600;
  text-transform: uppercase;
  letter-spacing: 0.1em;
  padding: 0.75rem 1.5rem;
  border: none;
  border-radius: var(--radius);
  cursor: pointer;
  transition: all var(--transition);
  display: inline-flex;
  align-items: center;
  justify-content: center;
  gap: 0.5rem;
}

.btn-primary {
  background: var(--red-primary);
  color: var(--text-white);
}

.btn-primary:hover {
  background: var(--red-dark);
  transform: translateY(-2px);
}

.btn-outline {
  background: transparent;
  color: var(--text-white);
  border: 2px solid var(--text-white);
}

.btn-outline:hover {
  background: var(--text-white);
  color: var(--bg-primary);
}

.btn-dark {
  background: var(--bg-secondary);
  color: var(--text-white);
  border: 1px solid var(--border-color);
}

.btn-dark:hover {
  background: var(--bg-card);
  border-color: var(--red-primary);
}

/* Mobile Menu */
.mobile-menu-btn {
  display: none;
  flex-direction: column;
  gap: 5px;
  background: none;
  border: none;
  cursor: pointer;
  padding: 5px;
}

.mobile-menu-btn span {
  width: 25px;
  height: 2px;
  background: var(--text-white);
  transition: var(--transition);
}

/* Hero Section */
.hero {
  min-height: 100vh;
  display: flex;
  align-items: center;
  justify-content: center;
  text-align: center;
  padding: 8rem 2rem 4rem;
  position: relative;
  overflow: hidden;
}

.hero::before {
  content: '';
  position: absolute;
  inset: 0;
  background: radial-gradient(ellipse at center, rgba(230, 57, 70, 0.1) 0%, transparent 70%);
  pointer-events: none;
}

.hero-content {
  max-width: 900px;
  position: relative;
  z-index: 1;
}

.hero h1 {
  font-size: clamp(2.5rem, 8vw, 5rem);
  margin-bottom: 1.5rem;
  color: var(--text-white);
}

.hero h1 span {
  color: var(--red-primary);
}

.hero-subtitle {
  font-size: 1.125rem;
  color: var(--text-gray);
  margin-bottom: 2rem;
  max-width: 600px;
  margin-left: auto;
  margin-right: auto;
}

.hero-cta {
  display: flex;
  gap: 1rem;
  justify-content: center;
  flex-wrap: wrap;
}

/* Top Promo Bar */
.promo-bar {
  background: var(--red-primary);
  padding: 0.75rem 2rem;
  text-align: center;
}

.promo-bar p {
  font-family: var(--font-heading);
  font-size: 0.875rem;
  text-transform: uppercase;
  letter-spacing: 0.1em;
}

.promo-bar a {
  text-decoration: underline;
  font-weight: 600;
}

/* Section Styles */
.section {
  padding: 5rem 2rem;
}

.section-dark {
  background: var(--bg-secondary);
}

.section-inner {
  max-width: 1200px;
  margin: 0 auto;
}

.section-header {
  text-align: center;
  margin-bottom: 3rem;
}

.section-header h2 {
  font-size: clamp(2rem, 5vw, 3rem);
  margin-bottom: 1rem;
}

.section-header p {
  color: var(--text-gray);
  max-width: 600px;
  margin: 0 auto;
}

/* Community Promo */
.community-grid {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 4rem;
  align-items: center;
}

.community-content h2 {
  font-size: clamp(2rem, 4vw, 3rem);
  margin-bottom: 1.5rem;
}

.community-content h2 span {
  color: var(--red-primary);
}

.community-content p {
  color: var(--text-gray);
  margin-bottom: 2rem;
  font-size: 1.125rem;
}

.community-image {
  position: relative;
  border-radius: var(--radius);
  overflow: hidden;
}

.community-image img {
  width: 100%;
  height: 400px;
  object-fit: cover;
}

.community-image::after {
  content: '';
  position: absolute;
  inset: 0;
  background: linear-gradient(to top, rgba(230, 57, 70, 0.3), transparent);
}

/* Two Ways Section */
.ways-grid {
  display: grid;
  grid-template-columns: repeat(2, 1fr);
  gap: 2rem;
}

.way-card {
  background: var(--bg-card);
  border: 1px solid var(--border-color);
  border-radius: var(--radius);
  padding: 3rem;
  text-align: center;
  transition: all var(--transition);
}

.way-card:hover {
  border-color: var(--red-primary);
  transform: translateY(-5px);
}

.way-card h3 {
  font-size: 1.5rem;
  margin-bottom: 1rem;
  color: var(--red-primary);
}

.way-card p {
  color: var(--text-gray);
}

/* Carousel */
.carousel {
  position: relative;
  overflow: hidden;
  border-radius: var(--radius);
}

.carousel-track {
  display: flex;
  transition: transform 500ms ease;
}

.carousel-slide {
  min-width: 100%;
  position: relative;
}

.carousel-slide img {
  width: 100%;
  height: 500px;
  object-fit: cover;
}

.carousel-slide::after {
  content: '';
  position: absolute;
  inset: 0;
  background: linear-gradient(to top, rgba(17, 17, 17, 0.7), transparent 50%);
}

.carousel-caption {
  position: absolute;
  bottom: 2rem;
  left: 2rem;
  right: 2rem;
  z-index: 1;
}

.carousel-caption h3 {
  font-size: 1.5rem;
  margin-bottom: 0.5rem;
}

.carousel-caption p {
  color: var(--text-gray);
}

.carousel-nav {
  position: absolute;
  top: 50%;
  transform: translateY(-50%);
  z-index: 2;
  background: rgba(17, 17, 17, 0.8);
  border: none;
  color: var(--text-white);
  width: 50px;
  height: 50px;
  border-radius: 50%;
  cursor: pointer;
  display: flex;
  align-items: center;
  justify-content: center;
  transition: var(--transition);
}

.carousel-nav:hover {
  background: var(--red-primary);
}

.carousel-nav.prev {
  left: 1rem;
}

.carousel-nav.next {
  right: 1rem;
}

.carousel-dots {
  display: flex;
  justify-content: center;
  gap: 0.5rem;
  margin-top: 1rem;
}

.carousel-dot {
  width: 10px;
  height: 10px;
  border-radius: 50%;
  background: var(--text-muted);
  border: none;
  cursor: pointer;
  transition: var(--transition);
}

.carousel-dot.active {
  background: var(--red-primary);
}

/* Newsletter */
.newsletter {
  background: var(--bg-secondary);
  padding: 4rem 2rem;
}

.newsletter-inner {
  max-width: 600px;
  margin: 0 auto;
  text-align: center;
}

.newsletter h2 {
  font-size: 2rem;
  margin-bottom: 1rem;
}

.newsletter p {
  color: var(--text-gray);
  margin-bottom: 2rem;
}

.newsletter-form {
  display: flex;
  gap: 1rem;
  max-width: 500px;
  margin: 0 auto;
}

.newsletter-form input {
  flex: 1;
  padding: 1rem 1.5rem;
  background: var(--bg-primary);
  border: 1px solid var(--border-color);
  border-radius: var(--radius);
  color: var(--text-white);
  font-size: 1rem;
  transition: border-color var(--transition);
}

.newsletter-form input:focus {
  outline: none;
  border-color: var(--red-primary);
}

.newsletter-form input.error {
  border-color: #ff4444;
}

.newsletter-form input.success {
  border-color: #44ff44;
}

.newsletter-message {
  margin-top: 1rem;
  font-size: 0.875rem;
}

.newsletter-message.error {
  color: #ff4444;
}

.newsletter-message.success {
  color: #44ff44;
}

/* Footer */
.footer {
  background: var(--bg-primary);
  border-top: 1px solid var(--border-color);
  padding: 4rem 2rem 2rem;
}

.footer-inner {
  max-width: 1200px;
  margin: 0 auto;
}

.footer-grid {
  display: grid;
  grid-template-columns: 2fr repeat(3, 1fr);
  gap: 3rem;
  margin-bottom: 3rem;
}

.footer-brand .logo {
  margin-bottom: 1rem;
  display: inline-block;
}

.footer-brand p {
  color: var(--text-gray);
  max-width: 300px;
}

.footer-col h4 {
  font-size: 0.875rem;
  margin-bottom: 1.5rem;
  color: var(--text-white);
}

.footer-col ul {
  list-style: none;
}

.footer-col li {
  margin-bottom: 0.75rem;
}

.footer-col a {
  color: var(--text-gray);
  transition: color var(--transition);
}

.footer-col a:hover {
  color: var(--red-primary);
}

.footer-bottom {
  padding-top: 2rem;
  border-top: 1px solid var(--border-color);
  display: flex;
  justify-content: space-between;
  align-items: center;
  flex-wrap: wrap;
  gap: 1rem;
}

.footer-bottom p {
  color: var(--text-muted);
  font-size: 0.875rem;
}

.country-selector {
  position: relative;
}

.country-selector button {
  background: var(--bg-secondary);
  border: 1px solid var(--border-color);
  color: var(--text-white);
  padding: 0.5rem 1rem;
  border-radius: var(--radius);
  cursor: pointer;
  display: flex;
  align-items: center;
  gap: 0.5rem;
  font-size: 0.875rem;
}

.country-selector button:hover {
  border-color: var(--red-primary);
}

.country-dropdown {
  position: absolute;
  bottom: 100%;
  right: 0;
  background: var(--bg-card);
  border: 1px solid var(--border-color);
  border-radius: var(--radius);
  padding: 0.5rem;
  min-width: 150px;
  display: none;
  margin-bottom: 0.5rem;
}

.country-dropdown.show {
  display: block;
}

.country-dropdown a {
  display: block;
  padding: 0.5rem 1rem;
  color: var(--text-gray);
  border-radius: var(--radius);
  transition: var(--transition);
}

.country-dropdown a:hover {
  background: var(--red-primary);
  color: var(--text-white);
}

/* Page Hero (subpages) */
.page-hero {
  min-height: 50vh;
  display: flex;
  align-items: center;
  justify-content: center;
  text-align: center;
  padding: 8rem 2rem 4rem;
  position: relative;
}

.page-hero::before {
  content: '';
  position: absolute;
  inset: 0;
  background: radial-gradient(ellipse at center, rgba(230, 57, 70, 0.15) 0%, transparent 70%);
  pointer-events: none;
}

.page-hero h1 {
  font-size: clamp(2.5rem, 6vw, 4rem);
  margin-bottom: 1rem;
  position: relative;
  z-index: 1;
}

.page-hero p {
  color: var(--text-gray);
  font-size: 1.125rem;
  max-width: 600px;
  margin: 0 auto;
  position: relative;
  z-index: 1;
}

/* Toggle Switch */
.toggle-container {
  display: flex;
  justify-content: center;
  gap: 0;
  margin-bottom: 3rem;
}

.toggle-btn {
  font-family: var(--font-heading);
  font-size: 1rem;
  text-transform: uppercase;
  letter-spacing: 0.1em;
  padding: 1rem 2rem;
  background: var(--bg-card);
  border: 1px solid var(--border-color);
  color: var(--text-gray);
  cursor: pointer;
  transition: all var(--transition);
}

.toggle-btn:first-child {
  border-radius: var(--radius) 0 0 var(--radius);
}

.toggle-btn:last-child {
  border-radius: 0 var(--radius) var(--radius) 0;
}

.toggle-btn.active {
  background: var(--red-primary);
  border-color: var(--red-primary);
  color: var(--text-white);
}

.toggle-btn:hover:not(.active) {
  background: var(--bg-secondary);
  color: var(--text-white);
}

/* Schedule Table */
.schedule-table {
  width: 100%;
  border-collapse: collapse;
  margin-top: 2rem;
}

.schedule-table th,
.schedule-table td {
  padding: 1rem;
  text-align: left;
  border-bottom: 1px solid var(--border-color);
}

.schedule-table th {
  font-family: var(--font-heading);
  text-transform: uppercase;
  letter-spacing: 0.1em;
  color: var(--text-muted);
  font-size: 0.875rem;
}

.schedule-table td {
  font-size: 1rem;
}

.schedule-table tr:hover td {
  background: var(--bg-secondary);
}

/* Instructor Grid */
.filter-controls {
  display: flex;
  justify-content: center;
  gap: 1rem;
  margin-bottom: 3rem;
  flex-wrap: wrap;
}

.filter-btn {
  font-family: var(--font-heading);
  font-size: 0.875rem;
  text-transform: uppercase;
  letter-spacing: 0.1em;
  padding: 0.75rem 1.5rem;
  background: var(--bg-card);
  border: 1px solid var(--border-color);
  color: var(--text-gray);
  border-radius: var(--radius);
  cursor: pointer;
  transition: all var(--transition);
}

.filter-btn:hover,
.filter-btn.active {
  background: var(--red-primary);
  border-color: var(--red-primary);
  color: var(--text-white);
}

.instructor-grid {
  display: grid;
  grid-template-columns: repeat(auto-fill, minmax(280px, 1fr));
  gap: 2rem;
}

.instructor-card {
  background: var(--bg-card);
  border: 1px solid var(--border-color);
  border-radius: var(--radius);
  overflow: hidden;
  transition: all var(--transition);
}

.instructor-card:hover {
  border-color: var(--red-primary);
  transform: translateY(-5px);
}

.instructor-card img {
  width: 100%;
  height: 280px;
  object-fit: cover;
}

.instructor-info {
  padding: 1.5rem;
}

.instructor-info h3 {
  font-size: 1.25rem;
  margin-bottom: 0.5rem;
}

.instructor-info p {
  color: var(--text-muted);
  font-size: 0.875rem;
  margin-bottom: 1rem;
}

.instructor-info .location {
  color: var(--red-primary);
}

/* FAQ Accordion */
.faq-list {
  max-width: 800px;
  margin: 0 auto;
}

.faq-item {
  border-bottom: 1px solid var(--border-color);
}

.faq-question {
  width: 100%;
  background: none;
  border: none;
  padding: 1.5rem 0;
  display: flex;
  justify-content: space-between;
  align-items: center;
  cursor: pointer;
  text-align: left;
}

.faq-question h3 {
  font-size: 1.125rem;
  color: var(--text-white);
  transition: color var(--transition);
}

.faq-question:hover h3 {
  color: var(--red-primary);
}

.faq-question .icon {
  font-size: 1.5rem;
  color: var(--red-primary);
  transition: transform var(--transition);
}

.faq-item.open .faq-question .icon {
  transform: rotate(45deg);
}

.faq-answer {
  max-height: 0;
  overflow: hidden;
  transition: max-height 300ms ease;
}

.faq-item.open .faq-answer {
  max-height: 500px;
}

.faq-answer p {
  padding-bottom: 1.5rem;
  color: var(--text-gray);
  line-height: 1.8;
}

/* Feature Cards */
.feature-grid {
  display: grid;
  grid-template-columns: repeat(auto-fit, minmax(300px, 1fr));
  gap: 2rem;
}

.feature-card {
  background: var(--bg-card);
  border: 1px solid var(--border-color);
  border-radius: var(--radius);
  padding: 2rem;
  transition: all var(--transition);
}

.feature-card:hover {
  border-color: var(--red-primary);
  transform: translateY(-5px);
}

.feature-card .icon {
  width: 60px;
  height: 60px;
  background: var(--red-primary);
  border-radius: var(--radius);
  display: flex;
  align-items: center;
  justify-content: center;
  margin-bottom: 1.5rem;
  font-size: 1.5rem;
}

.feature-card h3 {
  font-size: 1.25rem;
  margin-bottom: 1rem;
}

.feature-card p {
  color: var(--text-gray);
}

/* CTA Section */
.cta-section {
  background: var(--red-primary);
  padding: 4rem 2rem;
  text-align: center;
}

.cta-section h2 {
  font-size: clamp(2rem, 4vw, 3rem);
  margin-bottom: 1rem;
}

.cta-section p {
  margin-bottom: 2rem;
  opacity: 0.9;
}

.cta-section .btn {
  background: var(--bg-primary);
  color: var(--text-white);
}

.cta-section .btn:hover {
  background: var(--bg-secondary);
}

/* Free Trial CTA */
.free-trial {
  background: linear-gradient(135deg, var(--red-dark) 0%, var(--red-primary) 100%);
  padding: 5rem 2rem;
  text-align: center;
}

.free-trial h2 {
  font-size: clamp(2rem, 5vw, 3.5rem);
  margin-bottom: 1.5rem;
}

.free-trial .btn {
  background: var(--bg-primary);
  color: var(--text-white);
  font-size: 1rem;
  padding: 1rem 2.5rem;
}

.free-trial .btn:hover {
  background: var(--bg-secondary);
}

/* Workout Content */
.workout-content {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 3rem;
  align-items: start;
}

.workout-content img {
  width: 100%;
  height: 400px;
  object-fit: cover;
  border-radius: var(--radius);
}

.workout-text h3 {
  font-size: 1.5rem;
  margin-bottom: 1rem;
  color: var(--red-primary);
}

.workout-text p {
  color: var(--text-gray);
  line-height: 1.8;
}

/* Responsive */
@media (max-width: 1024px) {
  .footer-grid {
    grid-template-columns: 1fr 1fr;
  }

  .community-grid {
    grid-template-columns: 1fr;
  }

  .ways-grid {
    grid-template-columns: 1fr;
  }

  .workout-content {
    grid-template-columns: 1fr;
  }
}

@media (max-width: 768px) {
  .nav-links {
    display: none;
  }

  .mobile-menu-btn {
    display: flex;
  }

  .nav-links.open {
    display: flex;
    flex-direction: column;
    position: absolute;
    top: 100%;
    left: 0;
    right: 0;
    background: var(--bg-primary);
    padding: 1rem;
    border-bottom: 1px solid var(--border-color);
  }

  .footer-grid {
    grid-template-columns: 1fr;
  }

  .newsletter-form {
    flex-direction: column;
  }

  .hero-cta {
    flex-direction: column;
    align-items: center;
  }

  .carousel-slide img {
    height: 350px;
  }

  .toggle-container {
    flex-direction: column;
    align-items: stretch;
  }

  .toggle-btn:first-child,
  .toggle-btn:last-child {
    border-radius: var(--radius);
  }

  .filter-controls {
    flex-direction: column;
    align-items: stretch;
  }

  .filter-btn {
    text-align: center;
  }
}
